-- 1898: SG footer (block_footer_column5, block_id 7): the "Regional Training Centers"
--       section (one item, "Singapore (Headquarter)") becomes "Training Franchisee",
--       listing Tertiary Courses Malaysia (www.tertiarycourses.com.my) and
--       Tertiary Courses Ghana (www.tertiarycourses.com.gh), same numbered-badge markup.
--       Byte-exact REPLACE() via UNHEX() of the live block bytes; no-op if the prod
--       block differs. SG-only: partner footers are their own blocks.

UPDATE cms_block SET content = REPLACE(content, UNHEX(''), UNHEX(''))
WHERE block_id = 7 AND identifier = 'block_footer_column5' AND @mms_instance = 'SG';
